/**
 * Fails if the built service worker could pin an open install to an old build again.
 *
 * `dist/sw.js` is generated by Workbox from `vite.config.ts`, and its routing rests on defaults
 * that are easy to bring back by accident (`navigateFallback`, `directoryIndex`). On 2026-11-12 a
 * phone opened the app on a build four deploys old: the old worker answered every navigation
 * from its precache, and the new worker never finished installing. These are the rules that stop
 * it, checked on the file the browser actually runs:
 *
 *  - a navigation goes to the network (`NetworkOnly`), with the precached `index.html` behind it
 *    for when the network fails;
 *  - no `NavigationRoute` (cache-first `index.html` for every navigation), and `directoryIndex`
 *    is off, so the precache route cannot answer `/` before the navigation rule does;
 *  - `index.html` is still precached, so an offline open still has a shell;
 *  - no route caches anything at runtime (CLAUDE.md: the API is never cached);
 *  - the push handlers are still imported, and the update lifecycle is still `autoUpdate`'s.
 *
 *   npm run check:bundle
 */
import { existsSync, readFileSync } from 'node:fs'
import { join } from 'node:path'

const DIST = 'dist'
const SW = join(DIST, 'sw.js')

if (!existsSync(SW)) {
  console.error(`No ${SW}. Run the build first.`)
  process.exit(1)
}

const sw = readFileSync(SW, 'utf8')

const rules: readonly { rule: string; holds: boolean }[] = [
  {
    rule: 'navigations are NetworkOnly with the precached index.html as the fallback',
    holds:
      /registerRoute\(\s*\(\s*\{\s*request:\s*(\w+)\s*\}\s*\)\s*=>\s*(?:"navigate"\s*===\s*\1\.mode|\1\.mode\s*===\s*"navigate")\s*,\s*new\s+\w+\.NetworkOnly\(\s*\{\s*plugins:\s*\[\s*new\s+\w+\.PrecacheFallbackPlugin\(\s*\{\s*fallbackURL:\s*"[^"]*index\.html"/.test(
        sw,
      ),
  },
  {
    rule: 'no NavigationRoute answers navigations from the precache',
    holds: !/NavigationRoute|createHandlerBoundToURL/.test(sw),
  },
  {
    rule: 'the precache route does not map "/" to index.html (directoryIndex: null)',
    holds: /precacheAndRoute\(\s*\[[\s\S]*?\]\s*,\s*\{[^}]*directoryIndex:\s*null/.test(sw),
  },
  {
    rule: 'index.html is still precached, for offline opens',
    holds: /\{\s*url:\s*"index\.html"\s*,\s*revision:/.test(sw),
  },
  {
    rule: 'no route caches at runtime (CacheFirst, NetworkFirst, StaleWhileRevalidate, CacheOnly)',
    holds: !/new\s+\w+\.(?:CacheFirst|NetworkFirst|StaleWhileRevalidate|CacheOnly)\b/.test(sw),
  },
  {
    rule: 'the push handlers are imported (importScripts("push-sw.js")) and shipped',
    holds: /importScripts\(\s*"push-sw\.js"\s*\)/.test(sw) && existsSync(join(DIST, 'push-sw.js')),
  },
  {
    rule: 'a new worker takes over at once (skipWaiting, clientsClaim) and old caches are cleared',
    holds:
      /self\.skipWaiting\(\)/.test(sw) &&
      /\.clientsClaim\(\)/.test(sw) &&
      /\.cleanupOutdatedCaches\(\)/.test(sw),
  },
]

const broken = rules.filter((r) => !r.holds)
if (broken.length > 0) {
  console.error('SERVICE WORKER RULES BROKEN (see vite.config.ts > VitePWA > workbox):')
  for (const { rule } of broken) console.error(`  ${rule}`)
  process.exit(1)
}

console.log(`Service worker ok: ${String(rules.length)} rules hold in ${SW}.`)
